# SECURE: Role-based guard
def require_role(*roles):
    def decorator(func):
        async def wrapper(*args, token: str, **kwargs):
            user = decode_token(token)
            if user.role not in roles:
                raise HTTPException(403, 'Insufficient permissions')
            return await func(*args, token=token, **kwargs)
        return wrapper
    return decorator

@app.delete('/api/admin/users/{user_id}')
@require_role('admin', 'superadmin')
async def delete_user(user_id: int, token: str):
    db.delete_user(user_id)

# SECURE: Rate limited + single-use validation
@app.post('/api/coupon/apply')
@limiter.limit('3/hour')  # Max 3 coupon attempts per hour per user
async def apply_coupon(code: str, current_user: User):
    coupon = db.get_coupon(code)
    if coupon.used_by and current_user.id in coupon.used_by:
        raise HTTPException(409, 'Coupon already used by this account')
    if coupon.max_uses and coupon.use_count >= coupon.max_uses:
        raise HTTPException(410, 'Coupon exhausted')
    db.apply_discount_atomic(current_user.id, coupon)

# SECURE: Strict allowlist validation
import ipaddress
from urllib.parse import urlparse

ALLOWED_DOMAINS = {'api.trusted-partner.com', 'cdn.myapp.com'}

def validate_url(url: str) -> bool:
    parsed = urlparse(url)
    if parsed.scheme not in ['https']:
        return False
    if parsed.hostname in ALLOWED_DOMAINS:
        return True
    try:  # Block private IPs
        ip = ipaddress.ip_address(parsed.hostname)
        return ip.is_global
    except ValueError:
        return False

@app.post('/api/fetch')
async def fetch_url(url: str):
    if not validate_url(url):
        raise HTTPException(400, 'URL not allowed')
    resp = requests.get(url)
    return resp.text

